1	using System.Runtime.InteropServices;
2	using System.ComponentModel;
3	using System.Diagnostics;
4	using Microsoft.Win32;
5	
6	namespace AltHenkan;
7	
8	internal sealed partial class AltInputService : IDisposable
9	{
10	    private const nuint OwnInputMarker = 0x414C5448;
11	
12	    private readonly NativeMethods.HookProc _keyboardCallback;
13	    private readonly NativeMethods.HookProc _nextKeyboardHook;
14	    private readonly NativeMethods.HookProc _mouseCallback;
15	    private readonly HashSet<uint> _nonAltKeysDown = [];
16	    private readonly AltState _leftAlt = new(AltSide.Left);
17	    private readonly AltState _rightAlt = new(AltSide.Right);
18	    private readonly DeferredControlState _leftControl = new(ModifierSides.Left);
19	    private readonly DeferredControlState _rightControl = new(ModifierSides.Right);
20	    private readonly EmacsKeyboardState _emacsState = new();
21	    private readonly bool _initialNativeCapsLockOn;
22	    private readonly DedicatedMessageLoop? _hookThread;
23	    private readonly InputPlatform _platform;
24	    private System.Windows.Forms.Timer? _maintenanceTimer;
25	    private nint _keyboardHook;
26	    private nint _mouseHook;
27	    private AppSettings _settings;
28	    private volatile bool _disposed;
29	    private bool _refreshRequested;
30	    private long _lastRefreshAtMilliseconds;
31	    private int _hookGeneration;
32	    private long _keyboardCallbackCount;
33	    private long _mouseCallbackCount;
34	    private long _suppressedKeyboardEventCount;
35	    private long _inputInjectionFailures;
36	    private long _lastStatusAtMilliseconds;
37	    private long _imeWidthCommandEvents;
38	    private int _inputInjectionDepth;
39	    private long _inputInjectionCalls;
40	    private int _maxInputInjectionDepth;
41	    private long _keyboardCallbacksDuringInjection;
42	    private long _altReconcileChecks;
43	    private long _altReconcileInjectionSkips;
44	    private long _altReconcileInjectionSkipsWithAlt;
45	    private int _maxAltReconcileInjectionDepth;
46	    private long _altStateRecoveries;
47	    private long _controlStateRecoveries;
48	
49	    public event Action<int>? InputInjectionFailed;
50	    public event Action<bool>? EmacsModeChanged;
51	
52	    public AltInputService(AppSettings settings) : this(settings, new InputPlatform())
53	    {
54	        _initialNativeCapsLockOn = (NativeMethods.GetKeyState((int)NativeMethods.VkCapsLock) & 1) != 0;
55	        _hookThread = new DedicatedMessageLoop(InitializeHookThread, CleanupHookThread);
56	        SystemEvents.PowerModeChanged += OnPowerModeChanged;
57	        SystemEvents.SessionSwitch += OnSessionSwitch;
58	    }
59	
60	    internal AltInputService(AppSettings settings, InputPlatform platform)
61	    {
62	        _platform = platform;
63	        _settings = settings.Normalize();
64	        _emacsState.SetActive(_settings.InitialEmacsActive);
65	        _keyboardCallback = KeyboardHookCallback;
66	        _nextKeyboardHook = (code, wParam, lParam) =>
67	            _platform.NextKeyboard(_keyboardHook, code, wParam, lParam);
68	        _mouseCallback = MouseHookCallback;
69	    }
70	
71	    private void InitializeHookThread()
72	    {
73	        DiagnosticLog.Write($"Dedicated hook thread started: managed thread {Environment.CurrentManagedThreadId}.");
74	        DiagnosticLog.Write($"Initial keyboard mode: {(_emacsState.Active ? "Emacs" : "Normal")}.");
75	        RegisterHooks();
76	        _lastStatusAtMilliseconds = Environment.TickCount64;
77	        WriteHookStatus("startup");
78	        TraceSettings(after: true);
79	        EnsureNativeCapsLockOff(_initialNativeCapsLockOn);
80	        _maintenanceTimer = new System.Windows.Forms.Timer { Interval = 1000 };
81	        _maintenanceTimer.Tick += (_, _) => MaintainHooks();
82	        _maintenanceTimer.Start();
83	    }
84	
85	    private void RegisterHooks()
86	    {
87	        var module = NativeMethods.GetModuleHandle(null);
88	        var keyboardHook = NativeMethods.SetWindowsHookEx(
89	            NativeMethods.WhKeyboardLl,
90	            _keyboardCallback,
91	            module,
92	            0);
93	        if (keyboardHook == 0)
94	        {
95	            throw new Win32Exception(Marshal.GetLastWin32Error(), "キーボードフックを登録できませんでした。");
96	        }
97	
98	        var mouseHook = NativeMethods.SetWindowsHookEx(
99	            NativeMethods.WhMouseLl,
100	            _mouseCallback,
101	            module,
102	            0);
103	        if (mouseHook == 0)
104	        {
105	            var errorCode = Marshal.GetLastWin32Error();
106	            NativeMethods.UnhookWindowsHookEx(keyboardHook);
107	            throw new Win32Exception(errorCode, "マウスフックを登録できませんでした。");
108	        }
109	
110	        // Install replacements first: a failed renewal must not discard a working pair.
111	        UnregisterHooks();
112	        _keyboardHook = keyboardHook;
113	        _mouseHook = mouseHook;
114	        _lastRefreshAtMilliseconds = Environment.TickCount64;
115	        _refreshRequested = false;
116	        _hookGeneration++;
117	        Trace(new() { Kind = InputTraceKind.Boundary, Reason = InputTraceReason.Registered, Index = _hookGeneration });
118	        DiagnosticLog.Write(
119	            $"Hooks registered: generation={_hookGeneration}, keyboard=0x{_keyboardHook:X}, mouse=0x{_mouseHook:X}, keyboard callbacks={_keyboardCallbackCount}, mouse callbacks={_mouseCallbackCount}.");
120	    }
121	
122	    public void UpdateSettings(AppSettings settings)
123	    {
124	        var normalized = settings.Normalize();
125	        // GetKeyState is queue-relative: read on the UI caller, not the hook-only thread.
126	        var nativeCapsLockOn = (NativeMethods.GetKeyState((int)NativeMethods.VkCapsLock) & 1) != 0;
127	        PostToHookThread(() =>
128	        {
129	            TraceSettings(after: false);
130	            var wasEnabled = _settings.Enabled;
131	            var wasEmacsEnabled = _settings.Enabled && _settings.EmacsEnabled;
132	            _settings = normalized;
133	            WriteHookStatus("settings changed");
134	
135	            if (!_settings.Enabled || !_settings.EmacsEnabled)
136	            {
137	                if (_emacsState.Disable())
138	                {
139	                    NotifyEmacsModeChanged();
140	                }
141	            }
142	            else if (!wasEmacsEnabled)
143	            {
144	                _emacsState.SetActive(_settings.EmacsInitialMode == EmacsInitialMode.Emacs);
145	                EnsureNativeCapsLockOff(nativeCapsLockOn);
146	                NotifyEmacsModeChanged();
147	            }
148	
149	            if (wasEnabled && !_settings.Enabled)
150	            {
151	                ResetActiveStates(resetEmacsTransient: false, reason: InputTraceReason.Disabled);
152	            }
153	            else if (!wasEnabled && _settings.Enabled)
154	            {
155	                RequestRefresh("enabled");
156	            }
157	            TraceSettings(after: true);
158	        });
159	    }
160	
161	    private async void PostToHookThread(Action action)
162	    {
163	        if (_disposed)
164	        {
165	            return;
166	        }
167	
168	        try
169	        {
170	            if (_hookThread is not null) await _hookThread.InvokeAsync(action).ConfigureAwait(false);
171	            else action(); // The test platform has no dedicated message loop.
172	        }
173	        catch (Exception exception)
174	        {
175	            DiagnosticLog.Write($"Hook-thread command failed: {exception}");
176	        }
177	    }
178	
179	    private nint KeyboardHookCallback(int code, nint wParam, nint lParam)
180	    {
181	        var startedAt = Stopwatch.GetTimestamp();
182	        _keyboardCallbackCount++;
183	        if (_inputInjectionDepth > 0) _keyboardCallbacksDuringInjection++;
184	        try
185	        {
186	            return InputTrace.Enabled ? TraceKeyboard(code, wParam, lParam) : KeyboardHookCore(code, wParam, lParam);
187	        }
188	        catch (Exception exception)
189	        {
190	            _refreshRequested = true;
191	            DiagnosticLog.Write($"Keyboard callback failed; renewal requested: {exception}");
192	            return _nextKeyboardHook(code, wParam, lParam);
193	        }
194	        finally
195	        {
196	            var elapsed = Stopwatch.GetElapsedTime(startedAt);
197	            if (elapsed.TotalMilliseconds >= 100)
198	            {
199	                DiagnosticLog.Write($"Slow keyboard callback: {elapsed.TotalMilliseconds:F1} ms.");
200	            }
201	        }
202	    }
203	
204	    private nint KeyboardHookCore(int code, nint wParam, nint lParam)
205	    {
206	        if (code < 0 || _disposed)
207	        {
208	            return ForwardKeyboard(code, wParam, lParam);
209	        }
210	
211	        var data = Marshal.PtrToStructure<NativeMethods.KbdLlHookStruct>(lParam);
212	        if (IsOwnInput(data.ExtraInfo))
213	        {
214	            if (DiagnosticLog.VerboseEnabled) DiagnosticLog.WriteVerbose(
215	                $"Injected keyboard event observed: message=0x{unchecked((int)wParam):X4}, vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
216	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.OwnInput);
217	        }
218	
219	        var message = unchecked((int)wParam);
220	        var isKeyDown = message is NativeMethods.WmKeyDown or NativeMethods.WmSysKeyDown;
221	        var isKeyUp = message is NativeMethods.WmKeyUp or NativeMethods.WmSysKeyUp;
222	        if (!isKeyDown && !isKeyUp)
223	        {
224	            return ForwardKeyboard(code, wParam, lParam);
225	        }
226	
227	        // These IME commands can remain set in GetAsyncKeyState. Pass them through,
228	        // but do not retain them as held keys or promote pending Alt/Ctrl gestures.
229	        if (KeyHoldPolicy.IsWidthKeyCode(data.VirtualKeyCode) &&
230	            KeyHoldPolicy.IsImeWidthCommand(data.VirtualKeyCode, GetForegroundKeyboardLayout()))
231	        {
232	            _nonAltKeysDown.Remove(data.VirtualKeyCode);
233	            _imeWidthCommandEvents++;
234	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ImeWidth);
235	        }
236	
237	        var isExtended = (data.Flags & NativeMethods.LlkhfExtended) != 0;
238	
239	        var emacsEnabled = _settings.Enabled && _settings.EmacsEnabled;
240	        if (data.VirtualKeyCode == NativeMethods.VkCapsLock &&
241	            _emacsState.HandleCapsLock(isKeyDown, emacsEnabled, out var modeChanged))
242	        {
243	            ConsumePendingAltGestures();
244	            if (modeChanged)
245	            {
246	                NotifyEmacsModeChanged();
247	            }
248	            return SuppressKeyboardEvent(InputTraceReason.CapsLock);
249	        }
250	
251	        if (data.VirtualKeyCode == NativeMethods.VkLControl ||
252	            data.VirtualKeyCode == NativeMethods.VkControl && !isExtended)
253	        {
254	            return HandleControlEvent(_leftControl, code, wParam, lParam, data, isKeyDown);
255	        }
256	
257	        if (data.VirtualKeyCode == NativeMethods.VkRControl ||
258	            data.VirtualKeyCode == NativeMethods.VkControl && isExtended)
259	        {
260	            return HandleControlEvent(_rightControl, code, wParam, lParam, data, isKeyDown);
261	        }
262	
263	        var inspectModifiers = isKeyDown && emacsEnabled && _emacsState.Active && EmacsBindings.IsSourceKey(data.VirtualKeyCode);
264	        var controlSnapshot = inspectModifiers ? GetControlModifierSnapshot() : default;
265	        var modifiers = inspectModifiers ? GetNavigationModifiers(controlSnapshot) : NavigationModifiers.None;
266	        if (_emacsState.HandleKey(data.VirtualKeyCode, isKeyDown, emacsEnabled,
267	            modifiers, _settings.EmacsShortcuts, out var binding,
268	            modifiers == NavigationModifiers.None ? null : GetEmacsSideFilter(controlSnapshot)))
269	        {
270	            if (binding is not null)
271	            {
272	                if ((binding.Modifiers & NavigationModifiers.Alt) != 0)
273	                {
274	                    ConsumePendingAltGestures();
275	                }
276	                if ((binding.Modifiers & NavigationModifiers.Control) != 0)
277	                {
278	                    ConsumePendingControlGestures(controlSnapshot.Sides);
279	                }
280	                SendNavigation(binding);
281	            }
282	            return SuppressKeyboardEvent(InputTraceReason.Emacs);
283	        }
284	
285	        if (!_settings.Enabled)
286	        {
287	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.Inactive);
288	        }
289	
290	        PromotePendingControlsToNative();
291	
292	        if (data.VirtualKeyCode == NativeMethods.VkLMenu ||
293	            data.VirtualKeyCode == NativeMethods.VkMenu && !isExtended)
294	        {
295	            DiagnosticLog.WriteVerbose(
296	                $"Left Alt {(isKeyDown ? "down" : "up")}: vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
297	            return HandleAltEvent(_leftAlt, code, wParam, lParam, data, isKeyDown);
298	        }
299	
300	        if (data.VirtualKeyCode == NativeMethods.VkRMenu ||
301	            data.VirtualKeyCode == NativeMethods.VkMenu && isExtended)
302	        {
303	            DiagnosticLog.WriteVerbose(
304	                $"Right Alt {(isKeyDown ? "down" : "up")}: vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
305	            return HandleAltEvent(_rightAlt, code, wParam, lParam, data, isKeyDown);
306	        }
307	
308	        if (_leftAlt.IsDown || _rightAlt.IsDown)
309	        {
310	            if (IsShiftKey(data.VirtualKeyCode) && isKeyDown && CanDeferAltShift())
311	            {
312	                // Alt+< / Alt+> need Shift. Keep pending Alt hidden until the next key.
313	                MarkDeferredShiftChord();
314	            }
315	            else if (!(IsShiftKey(data.VirtualKeyCode) && isKeyUp &&
316	                (_leftAlt.ConsumedByEmacs || _rightAlt.ConsumedByEmacs)))
317	            {
318	                PromotePendingAltsToNative();
319	            }
320	        }
321	
322	        if (isKeyDown)
323	        {
324	            _nonAltKeysDown.Add(data.VirtualKeyCode);
325	        }
326	        else
327	        {
328	            _nonAltKeysDown.Remove(data.VirtualKeyCode);
329	        }
330	
331	        return ForwardKeyboard(code, wParam, lParam);
332	    }
333	
334	    private nint HandleControlEvent(
335	        DeferredControlState state,
336	        int code, nint wParam, nint lParam,
337	        NativeMethods.KbdLlHookStruct data, bool isKeyDown)
338	    {
339	        var downVersion = state.ReleaseAudit.Begin(isKeyDown);
340	        try { return HandleControlEventCore(state, code, wParam, lParam, data, isKeyDown); }
341	        finally
342	        {
343	            if (!isKeyDown && state.ReleaseAudit.DownVersion == downVersion)
344	                CheckModifierRelease(ref state.ReleaseAudit,
345	                    state.Side == ModifierSides.Left ? InputTraceKey.LeftControl : InputTraceKey.RightControl,
346	                    ModifierResidual(state.IsDown, state.OriginalDownPassed, state.NativeDownSent, state.ConsumedByEmacs), data);
347	        }
348	    }
349	
350	    private nint HandleControlEventCore(
351	        DeferredControlState state,
352	        int code,
353	        nint wParam,
354	        nint lParam,
355	        NativeMethods.KbdLlHookStruct data,
356	        bool isKeyDown)
357	    {
358	        if (isKeyDown)
359	        {
360	            state.ReleaseMonitor.Reset();
361	            if (state.IsDown)
362	            {
363	                if (state.OriginalDownPassed || state.NativeDownSent)
364	                {
365	                    // This can be a new press after a missed up, as with native Alt.
366	                    state.OriginalDownPassed = true;
367	                    state.NativeDownSent = false;
368	                    return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlRepeatNative);
369	                }
370	                return SuppressKeyboardEvent(InputTraceReason.ControlRepeat);
371	            }
372	
373	            state.Start(data.ScanCode, (data.Flags & NativeMethods.LlkhfExtended) != 0);
374	            var canDefer = CanDeferControl(state);
375	            if (!canDefer || IsAnyOtherInputDownForControl())
376	            {
377	                state.OriginalDownPassed = true;
378	                return ForwardKeyboard(code, wParam, lParam, canDefer
379	                    ? InputTraceReason.ControlNativeOtherInput : InputTraceReason.ControlNativeNotDeferrable);
380	            }
381	
382	            var otherControl = state.Side == ModifierSides.Left ? _rightControl : _leftControl;
383	            if (otherControl.IsDown)
384	            {
385	                PromotePendingControlToNative(otherControl);
386	                PromotePendingControlToNative(state);
387	            }
388	            return SuppressKeyboardEvent(InputTraceReason.ControlDeferred);
389	        }
390	
391	        if (!state.IsDown)
392	        {
393	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlUnknownUp);
394	        }
395	
396	        state.IsDown = false;
397	        if (state.OriginalDownPassed)
398	        {
399	            state.Reset();
400	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlPassedUp);
401	        }
402	
403	        if (state.NativeDownSent)
404	        {
405	            SendControl(state, keyUp: true);
406	            state.Reset();
407	            return SuppressKeyboardEvent(InputTraceReason.ControlSentUp);
408	        }
409	
410	        if (!state.ConsumedByEmacs)
411	        {
412	            SendControl(state, keyUp: false);
413	            SendControl(state, keyUp: true);
414	        }
415	        state.Reset();
416	        return SuppressKeyboardEvent(InputTraceReason.ControlTapOrConsumed);
417	    }
