419	    private nint HandleAltEvent(
420	        AltState state,
421	        int code, nint wParam, nint lParam,
422	        NativeMethods.KbdLlHookStruct data, bool isKeyDown)
423	    {
424	        var downVersion = state.ReleaseAudit.Begin(isKeyDown);
425	        try { return HandleAltEventCore(state, code, wParam, lParam, data, isKeyDown); }
426	        finally
427	        {
428	            if (!isKeyDown && state.ReleaseAudit.DownVersion == downVersion)
429	                CheckModifierRelease(ref state.ReleaseAudit,
430	                    state.Side == AltSide.Left ? InputTraceKey.LeftAlt : InputTraceKey.RightAlt,
431	                    ModifierResidual(state.IsDown, state.OriginalDownPassed, state.NativeDownSent, state.ConsumedByEmacs,
432	                        state.DeferredShiftChord), data);
433	        }
434	    }
435	
436	    private nint HandleAltEventCore(
437	        AltState state,
438	        int code,
439	        nint wParam,
440	        nint lParam,
441	        NativeMethods.KbdLlHookStruct data,
442	        bool isKeyDown)
443	    {
444	        if (isKeyDown)
445	        {
446	            // A down event invalidates release observations, even when it looks like a repeat.
447	            state.ReleaseMonitor.Reset();
448	            if (state.IsDown)
449	            {
450	                if (state.OriginalDownPassed || state.NativeDownSent)
451	                {
452	                    // This may be a new press after a missed up. Forward native Alt repeats
453	                    // too: swallowing this down would leave Windows up while the user holds Alt.
454	                    // Its physical up can now follow the physical down through the hook chain.
455	                    state.OriginalDownPassed = true;
456	                    state.NativeDownSent = false;
457	                    return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltRepeatNative);
458	                }
459	                return SuppressKeyboardEvent(InputTraceReason.AltRepeatHidden);
460	            }
461	
462	            state.Start(data.ScanCode, (data.Flags & NativeMethods.LlkhfExtended) != 0);
463	
464	            var otherAlt = state.Side == AltSide.Left ? _rightAlt : _leftAlt;
465	            if (otherAlt.IsDown)
466	            {
467	                PromotePendingAltToNative(otherAlt);
468	                PromotePendingAltToNative(state);
469	                return SuppressKeyboardEvent(InputTraceReason.AltDeferred);
470	            }
471	
472	            if (IsAnyNonAltKeyDown())
473	            {
474	                if (IsVirtualKeyDown(NativeMethods.VkShift) && CanDeferAltShift() &&
475	                    !_emacsState.GestureActive && _nonAltKeysDown.All(IsShiftKey))
476	                {
477	                    state.DeferredShiftChord = true;
478	                }
479	                else
480	                {
481	                    state.OriginalDownPassed = true;
482	                    return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltNative);
483	                }
484	            }
485	
486	            return SuppressKeyboardEvent(InputTraceReason.AltDeferred);
487	        }
488	
489	        if (!state.IsDown)
490	        {
491	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltUnknownUp);
492	        }
493	
494	        var heldMilliseconds = Environment.TickCount64 - state.DownAtMilliseconds;
495	        state.IsDown = false;
496	
497	        if (state.OriginalDownPassed)
498	        {
499	            state.Reset();
500	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltPassedUp);
501	        }
502	
503	        if (state.NativeDownSent)
504	        {
505	            DiagnosticLog.WriteVerbose($"{state.Side} Alt used with another input; sending native Alt up.");
506	            SendAlt(state, keyUp: true);
507	            state.Reset();
508	            return SuppressKeyboardEvent(InputTraceReason.AltSentUp);
509	        }
510	
511	        if (state.ConsumedByEmacs)
512	        {
513	            state.Reset();
514	            return SuppressKeyboardEvent(InputTraceReason.AltConsumed);
515	        }
516	
517	        if (state.DeferredShiftChord)
518	        {
519	            // No angle shortcut followed: preserve the native Alt+Shift chord.
520	            SendAltTap(state);
521	            state.Reset();
522	            return SuppressKeyboardEvent(InputTraceReason.AltTap);
523	        }
524	
525	        var longPressEnabled = state.Side == AltSide.Left
526	            ? _settings.LeftAltLongPressEnabled
527	            : _settings.RightAltLongPressEnabled;
528	        var action = AltPressDecision.Decide(
529	            heldMilliseconds,
530	            longPressEnabled,
531	            _settings.LongPressMilliseconds);
532	
533	        if (action == AltPressAction.NativeAlt)
534	        {
535	            DiagnosticLog.WriteVerbose(
536	                $"{state.Side} Alt held for {heldMilliseconds} ms; sending native Alt tap.");
537	            SendAltTap(state);
538	        }
539	        else
540	        {
541	            DiagnosticLog.WriteVerbose(
542	                $"{state.Side} Alt held for {heldMilliseconds} ms; sending {(state.Side == AltSide.Left ? "IME off" : "IME on")} tap.");
543	            SendImeStateTap(state.Side);
544	        }
545	
546	        state.Reset();
547	        return SuppressKeyboardEvent(InputTraceReason.AltTap);
548	    }
