550	    private nint MouseHookCallback(int code, nint wParam, nint lParam)
551	    {
552	        var startedAt = Stopwatch.GetTimestamp();
553	        _mouseCallbackCount++;
554	        try
555	        {
556	            return InputTrace.Enabled ? TraceMouse(code, wParam, lParam) : MouseHookCore(code, wParam, lParam);
557	        }
558	        catch (Exception exception)
559	        {
560	            _refreshRequested = true;
561	            DiagnosticLog.Write($"Mouse callback failed; renewal requested: {exception}");
562	            return _platform.NextMouse(_mouseHook, code, wParam, lParam);
563	        }
564	        finally
565	        {
566	            var elapsed = Stopwatch.GetElapsedTime(startedAt);
567	            if (elapsed.TotalMilliseconds >= 100)
568	            {
569	                DiagnosticLog.Write($"Slow mouse callback: {elapsed.TotalMilliseconds:F1} ms.");
570	            }
571	        }
572	    }
