574	    private nint MouseHookCore(int code, nint wParam, nint lParam)
575	    {
576	        if (code >= 0 && !_disposed && _settings.Enabled && IsMouseInteraction(unchecked((int)wParam)))
577	        {
578	            PromotePendingControlsToNative();
579	            PromotePendingAltsToNative();
580	        }
581	
582	        return _platform.NextMouse(_mouseHook, code, wParam, lParam);
583	    }
