635	    private bool IsAnyNonAltKeyDown()
636	    {
637	        // A missed key-up must not classify every later Alt tap as a chord.
638	        KeyHoldPolicy.PruneNonAltKeys(_nonAltKeysDown, GetForegroundKeyboardLayout(), IsVirtualKeyDown);
639	        return _nonAltKeysDown.Count > 0 || _emacsState.GestureActive ||
640	               IsVirtualKeyDown(NativeMethods.VkShift) ||
641	               IsVirtualKeyDown(NativeMethods.VkControl) ||
642	               IsVirtualKeyDown(NativeMethods.VkLWin) ||
643	               IsVirtualKeyDown(NativeMethods.VkRWin);
644	    }
