646	    private bool IsAnyOtherInputDownForControl()
647	    {
648	        KeyHoldPolicy.PruneNonAltKeys(_nonAltKeysDown, GetForegroundKeyboardLayout(), IsVirtualKeyDown);
649	        return _nonAltKeysDown.Count > 0 || _leftAlt.IsDown || _rightAlt.IsDown ||
650	               IsVirtualKeyDown(NativeMethods.VkShift) ||
651	               IsVirtualKeyDown(NativeMethods.VkLWin) || IsVirtualKeyDown(NativeMethods.VkRWin);
