659	    private static nuint GetForegroundKeyboardLayout()
660	    {
661	        var window = NativeMethods.GetForegroundWindow();
662	        // An unknown foreground must not silently select the hook thread's layout.
663	        if (window == 0) return 0;
664	        var thread = NativeMethods.GetWindowThreadProcessId(window, out _);
665	        return thread == 0 ? 0 : unchecked((nuint)NativeMethods.GetKeyboardLayout(thread));
666	    }
