668	    private NavigationModifiers GetNavigationModifiers(ControlModifierSnapshot control)
669	    {
670	        var result = NavigationModifiers.None;
671	        if (control.AnyDown) result |= NavigationModifiers.Control;
672	        if (GetAltSnapshot(_leftAlt).Active || GetAltSnapshot(_rightAlt).Active ||
673	            IsVirtualKeyDown(NativeMethods.VkMenu)) result |= NavigationModifiers.Alt;
674	        if (IsVirtualKeyDown(NativeMethods.VkShift)) result |= NavigationModifiers.Shift;
675	        if (IsVirtualKeyDown(NativeMethods.VkLWin) || IsVirtualKeyDown(NativeMethods.VkRWin)) result |= NavigationModifiers.Windows;
676	        return result;
677	    }
