685	    private void ConsumePendingControlGestures(ModifierSides activeSides)
686	    {
687	        // Do not turn an excluded stale side into hidden Ctrl when the OTHER
688	        // side invokes a shortcut. Hidden state is eligible for reinjection.
689	        if ((activeSides & ModifierSides.Left) != 0) ConsumePendingControlGesture(_leftControl);
690	        if ((activeSides & ModifierSides.Right) != 0) ConsumePendingControlGesture(_rightControl);
691	    }
