693	    private void ConsumePendingControlGesture(DeferredControlState state)
694	    {
695	        if (!state.IsDown)
696	        {
697	            return;
698	        }
699	
700	        TraceState(InputTraceReason.ConsumeControl);
701	        if (state.OriginalDownPassed || state.NativeDownSent)
702	        {
703	            SendControl(state, keyUp: true);
704	            DiagnosticLog.WriteVerbose($"{state.Side} Ctrl returned to deferred state for Emacs input.");
705	        }
706	
707	        state.OriginalDownPassed = false;
708	        state.NativeDownSent = false;
709	        state.ConsumedByEmacs = true;
710	        state.ReleaseMonitor.Reset();
711	        TraceState(InputTraceReason.ConsumeControl, after: true);
712	    }
