748	    private void SendNavigation(EmacsBinding binding)
749	    {
750	        TraceState(InputTraceReason.Navigation);
751	        var modifiers = new List<ushort>();
752	        if (IsVirtualKeyDown(NativeMethods.VkLControl) && !_leftControl.HiddenFromForeground)
753	            modifiers.Add((ushort)NativeMethods.VkLControl);
754	        if (IsVirtualKeyDown(NativeMethods.VkRControl) && !_rightControl.HiddenFromForeground)
755	            modifiers.Add((ushort)NativeMethods.VkRControl);
756	        if (IsVirtualKeyDown(NativeMethods.VkLShift)) modifiers.Add((ushort)NativeMethods.VkLShift);
757	        if (IsVirtualKeyDown(NativeMethods.VkRShift)) modifiers.Add((ushort)NativeMethods.VkRShift);
758	        if (GetAltSnapshot(_leftAlt).ShouldRestore)
759	            modifiers.Add((ushort)NativeMethods.VkLMenu);
760	        if (GetAltSnapshot(_rightAlt).ShouldRestore)
761	            modifiers.Add((ushort)NativeMethods.VkRMenu);
762	
763	        var plan = NavigationInputPlan.Create(binding, modifiers);
764	        SendKeyboardInputsFor(InputTraceReason.Navigation,
765	            plan.Select(stroke => CreateNavigationKeyInput(stroke.VirtualKey, stroke.KeyUp)).ToArray());
766	        TraceState(InputTraceReason.Navigation, after: true);
767	        DiagnosticLog.WriteVerbose($"Emacs operation: {binding.Shortcut}.");
768	    }
