822	    private void SendKeyboardInputs(params NativeMethods.Input[] inputs)
823	        => SendKeyboardInputsFor(InputTraceReason.None, inputs);
824	
825	    private void SendKeyboardInputsFor(InputTraceReason reason, params NativeMethods.Input[] inputs)
826	    {
827	        var parentBatch = _traceBatch;
828	        _traceBatch = ++_traceBatchSequence;
829	        var started = Stopwatch.GetTimestamp();
830	        var result = new InputSendResult(0, 0);
831	        var completed = false;
832	        _inputInjectionDepth++;
833	        _inputInjectionCalls++;
834	        _maxInputInjectionDepth = Math.Max(_maxInputInjectionDepth, _inputInjectionDepth);
835	        try
836	        {
837	            Trace(new() { Kind = InputTraceKind.SendBegin, Reason = reason, ParentBatch = parentBatch, Requested = inputs.Length });
838	            for (var index = 0; index < inputs.Length; index++)
839	            {
840	                inputs[index].Data.Keyboard.ExtraInfo = NextInputMarker();
841	                var key = inputs[index].Data.Keyboard;
842	                Trace(new() { Kind = InputTraceKind.SendItem, Reason = reason, Index = index,
843	                    Token = TraceToken(key.ExtraInfo), SentScan = key.ScanCode, SentVirtualKey = key.VirtualKey,
844	                    Up = (key.Flags & NativeMethods.KeyeventfKeyUp) != 0, Flags = key.Flags, Own = true });
845	            }
846	            result = _platform.Send(inputs);
847	            completed = true;
848	            if (result.Sent == (uint)inputs.Length)
849	            {
850	                if (DiagnosticLog.VerboseEnabled)
851	                    DiagnosticLog.WriteVerbose($"SendInput succeeded for {inputs.Length} keyboard event(s).");
852	            }
853	            else
854	            {
855	                _inputInjectionFailures++;
856	                DiagnosticLog.Write(
857	                    $"SendInput failed: requested={inputs.Length}, sent={result.Sent}; Windows error={result.Error}.");
858	                InputInjectionFailed?.Invoke(result.Error);
859	            }
860	        }
861	        finally
862	        {
863	            Trace(new() { Kind = InputTraceKind.SendEnd, Reason = reason, ParentBatch = parentBatch,
864	                Requested = inputs.Length, Sent = result.Sent, Error = result.Error, Index = completed ? 1 : 0,
865	                ElapsedTicks = Stopwatch.GetTimestamp() - started });
866	            _inputInjectionDepth--;
867	            _traceBatch = parentBatch;
868	        }
869	    }
