871	    // Sends by virtual key (KEYEVENTF_SCANCODE deliberately omitted) so the IME
872	    // receives VK_IME_ON / VK_IME_OFF regardless of the hardware layout.
873	    private static NativeMethods.Input CreateVirtualKeyInput(ushort virtualKey, bool keyUp)
874	    {
875	        return new NativeMethods.Input
876	        {
877	            Type = NativeMethods.InputKeyboard,
878	            Data = new NativeMethods.InputUnion
879	            {
880	                Keyboard = new NativeMethods.KeyboardInput
881	                {
882	                    VirtualKey = virtualKey,
883	                    Flags = (keyUp ? NativeMethods.KeyeventfKeyUp : 0) |
884	                        (IsExtendedVirtualKey(virtualKey)
885	                            ? NativeMethods.KeyeventfExtendedKey : 0),
886	                    ExtraInfo = OwnInputMarker
887	                }
888	            }
889	        };
890	    }
891	
892	    private static NativeMethods.Input CreateNavigationKeyInput(ushort virtualKey, bool keyUp)
893	    {
894	        var mappedScanCode = NativeMethods.MapVirtualKey(virtualKey, NativeMethods.MapvkVkToVscEx);
895	        var scanCode = (ushort)(mappedScanCode & 0xFF);
896	        var prefix = mappedScanCode & 0xFF00;
897	        var isExtended = prefix is 0xE000 or 0xE100 || IsExtendedVirtualKey(virtualKey);
898	
899	        return CreateScanCodeInput(scanCode, isExtended, keyUp);
900	    }
901	
902	    private static bool IsExtendedVirtualKey(ushort virtualKey) =>
903	        virtualKey is (ushort)Keys.Left or (ushort)Keys.Right or (ushort)Keys.Up or (ushort)Keys.Down or
904	            (ushort)Keys.Home or (ushort)Keys.End or (ushort)Keys.Delete or
905	            (ushort)Keys.RControlKey or (ushort)Keys.RMenu;
906	
907	    private static NativeMethods.Input CreateScanCodeInput(ushort scanCode, bool isExtended, bool keyUp)
908	    {
909	        var flags = NativeMethods.KeyeventfScanCode;
910	        if (isExtended)
911	        {
912	            flags |= NativeMethods.KeyeventfExtendedKey;
913	        }
914	
915	        if (keyUp)
916	        {
917	            flags |= NativeMethods.KeyeventfKeyUp;
918	        }
919	
920	        return new NativeMethods.Input
921	        {
922	            Type = NativeMethods.InputKeyboard,
923	            Data = new NativeMethods.InputUnion
924	            {
925	                Keyboard = new NativeMethods.KeyboardInput
926	                {
927	                    ScanCode = scanCode,
928	                    Flags = flags,
929	                    ExtraInfo = OwnInputMarker
930	                }
931	            }
932	        };
933	    }
