935	    private void ResetActiveStates(bool resetEmacsTransient = true, InputTraceReason reason = InputTraceReason.Renewal)
936	    {
937	        Trace(new() { Kind = InputTraceKind.Boundary, Reason = reason });
938	        TraceState(InputTraceReason.ResetBegin);
939	        if (_leftAlt.IsDown || _rightAlt.IsDown || _leftControl.IsDown || _rightControl.IsDown ||
940	            _emacsState.GestureActive)
941	            WriteHookStatus("before active state reset");
942	        foreach (var state in new[] { _leftAlt, _rightAlt })
943	        {
944	            if (state.IsDown && state.NativeDownSent)
945	            {
946	                SendAlt(state, keyUp: true);
947	            }
948	
949	            state.Reset();
950	        }
951	
952	        foreach (var state in new[] { _leftControl, _rightControl })
953	        {
954	            if (state.IsDown && state.NativeDownSent)
955	            {
956	                SendControl(state, keyUp: true);
957	            }
958	
959	            state.Reset();
960	        }
961	
962	        _nonAltKeysDown.Clear();
963	        if (resetEmacsTransient) _emacsState.ResetTransient();
964	        TraceState(InputTraceReason.ResetEnd, after: true);
965	    }
