997	    private void MaintainHooks()
998	    {
999	        if (_disposed)
1000	        {
1001	            return;
1002	        }
1003	
1004	        try
1005	        {
1006	            ReconcileReleasedModifiers();
1007	            // Record even when a retained gesture prevents renewal indefinitely.
1008	            var now = Environment.TickCount64;
1009	            if (now - _lastStatusAtMilliseconds >= 30_000)
1010	            {
1011	                _lastStatusAtMilliseconds = now;
1012	                WriteHookStatus("periodic");
1013	            }
1014	            var info = new NativeMethods.LastInputInfo
1015	            {
1016	                Size = (uint)Marshal.SizeOf<NativeMethods.LastInputInfo>()
1017	            };
1018	            if (!NativeMethods.GetLastInputInfo(ref info))
1019	            {
1020	                return;
1021	            }
1022	
1023	            var idleMilliseconds = HookMaintenancePolicy.CalculateIdleMilliseconds(
1024	                unchecked((uint)Environment.TickCount), info.Time);
1025	            var gestureActive = _leftAlt.IsDown || _rightAlt.IsDown ||
1026	                _leftControl.IsDown || _rightControl.IsDown || _emacsState.GestureActive;
1027	            if (idleMilliseconds < HookMaintenancePolicy.MinimumIdleMilliseconds || gestureActive)
1028	            {
1029	                return;
1030	            }
1031	
1032	            // Includes real keys, modifiers and mouse buttons; excludes Japanese IME width commands.
1033	            var anyKeyDown = KeyHoldPolicy.AnyKeyOrMouseButtonDown(
1034	                GetForegroundKeyboardLayout(), IsVirtualKeyDown);
1035	
1036	            if (HookMaintenancePolicy.ShouldRefresh(
1037	                Environment.TickCount64 - _lastRefreshAtMilliseconds,
1038	                idleMilliseconds, anyKeyDown, gestureActive, _refreshRequested))
1039	            {
1040	                ResetActiveStates();
1041	                RegisterHooks();
1042	            }
1043	        }
1044	        catch (Exception exception)
1045	        {
1046	            _refreshRequested = true;
1047	            DiagnosticLog.Write($"Hook renewal failed; will retry at safe idle: {exception}");
1048	        }
1049	    }
