1080	    private void ReconcileReleasedModifiers()
1081	    {
1082	        _altReconcileChecks++;
1083	        // Do not interpret our temporary releases during SendInput as user releases.
1084	        if (_inputInjectionDepth != 0)
1085	        {
1086	            _altReconcileInjectionSkips++;
1087	            if (_leftAlt.IsDown || _rightAlt.IsDown) _altReconcileInjectionSkipsWithAlt++;
1088	            _maxAltReconcileInjectionDepth = Math.Max(_maxAltReconcileInjectionDepth, _inputInjectionDepth);
1089	            _leftAlt.ReleaseMonitor.Reset();
1090	            _rightAlt.ReleaseMonitor.Reset();
1091	            _leftControl.ReleaseMonitor.Reset();
1092	            _rightControl.ReleaseMonitor.Reset();
1093	            return;
1094	        }
1095	        // Cheap prefilter: no token/process/desktop queries while idle, hidden,
1096	        // or visibly held. A raw "up" only requests the guarded read; it never
1097	        // authorizes recovery by itself. Evaluate all sides to reset monitors.
1098	        var leftAlt = NeedsReleaseCheck(_leftAlt.IsDown, _leftAlt.OriginalDownPassed || _leftAlt.NativeDownSent,
1099	            NativeMethods.VkLMenu, _leftAlt.ReleaseMonitor);
1100	        var rightAlt = NeedsReleaseCheck(_rightAlt.IsDown, _rightAlt.OriginalDownPassed || _rightAlt.NativeDownSent,
1101	            NativeMethods.VkRMenu, _rightAlt.ReleaseMonitor);
1102	        var leftControl = NeedsReleaseCheck(_leftControl.IsDown, _leftControl.OriginalDownPassed || _leftControl.NativeDownSent,
1103	            NativeMethods.VkLControl, _leftControl.ReleaseMonitor);
1104	        var rightControl = NeedsReleaseCheck(_rightControl.IsDown, _rightControl.OriginalDownPassed || _rightControl.NativeDownSent,
1105	            NativeMethods.VkRControl, _rightControl.ReleaseMonitor);
1106	        if (!(leftAlt || rightAlt || leftControl || rightControl)) return;
1107	        var sample = _platform.ReadModifierState();
1108	        var now = _platform.MonotonicMilliseconds;
1109	        if (leftAlt) ReconcileReleasedAlt(_leftAlt, sample.Reliable, sample.Foreground, sample.LeftAltDown, now);
1110	        if (rightAlt) ReconcileReleasedAlt(_rightAlt, sample.Reliable, sample.Foreground, sample.RightAltDown, now);
1111	        if (leftControl) ReconcileReleasedControl(_leftControl, sample.Reliable, sample.Foreground, sample.LeftControlDown, now);
1112	        if (rightControl) ReconcileReleasedControl(_rightControl, sample.Reliable, sample.Foreground, sample.RightControlDown, now);
1113	    }
