1173	            $"refreshRequested={_refreshRequested}, sinceRefreshMs={Environment.TickCount64 - _lastRefreshAtMilliseconds}, " +
1174	            $"leftAlt={_leftAlt.IsDown}/{_leftAlt.OriginalDownPassed}/{_leftAlt.NativeDownSent}, " +
