6	internal static class ControlRecoveryTests
7	{
8	    private const BindingFlags Private = BindingFlags.Instance | BindingFlags.NonPublic;
9	    private static readonly uint[] Controls = [NativeMethods.VkLControl, NativeMethods.VkRControl];
10	
11	    public static void Run(Action<string, bool> check)
12	    {
13	        ReplayIncident(check);
14	        ForeignAltGrSequence(check);
15	        foreach (var key in Controls)
16	        foreach (var passed in new[] { false, true })
17	        {
18	            ExcludeStaleSide(key, passed, check);
19	            Repress(key, passed, check);
20	            Recover(key, passed, check);
21	            PreserveHeld(key, passed, check);
22	        }
23	        foreach (var key in Controls) PreserveHidden(key, check);
24	        SamplingAndCost(check);
25	        RecoveryLog(check);
26	    }
27	
28	    private static void ReplayIncident(Action<string, bool> check)
29	    {
30	        using var f = new Fixture();
31	        var key = NativeMethods.VkLControl;
32	        f.Key(key, false);
33	        f.Key(NativeMethods.VkLMenu, false);
34	        // Fault injection models missing hook ups and a released OS state;
35	        // it does not establish why Windows failed to deliver the real ups.
36	        f.Platform.SetDown(key, false);
37	        f.Platform.SetDown(NativeMethods.VkLMenu, false);
38	        var alt = typeof(AltInputService).GetField("_leftAlt", Private)!.GetValue(f.Service)!;
39	        var recoverAlt = typeof(AltInputService).GetMethod("ReconcileReleasedAlt", Private)!;
40	        recoverAlt.Invoke(f.Service, [alt, true, (nint)1, false, 1000L]);
41	        recoverAlt.Invoke(f.Service, [alt, true, (nint)1, false, 2000L]);
42	        f.Platform.Sent.Clear();
43	        check("Incident: ordinary F passes before Ctrl timer recovery", f.Key((uint)Keys.F, false) == 0);
44	        f.Key((uint)Keys.F, true);
45	        f.Tap((uint)Keys.X);
46	        f.Mouse();
47	        check("Incident: keyboard and mouse do not reinject stale Ctrl", f.Platform.Sent.Count == 0 && f.Platform.AllUp);
48	        check("Incident: callback exclusion does not prematurely reset Ctrl", f.Flag(key, "IsDown") && f.Flag(key, "NativeDownSent"));
49	        f.Tick();
50	        f.Tick(1000);
51	        check("Incident: guarded timer clears Ctrl without synthesizing input", !f.Flag(key, "IsDown") && f.Platform.Sent.Count == 0);
52	        check("Incident: late Ctrl up passes without a tap", f.Key(key, true) == 0 && f.Platform.Sent.Count == 0);
53	    }
54	
55	    private static void ForeignAltGrSequence(Action<string, bool> check)
56	    {
57	        // An AltGr-style event sequence, not a claim about the active OS layout.
58	        using var f = new Fixture();
59	        for (var i = 0; i < 3; i++)
60	        {
61	            f.Platform.Deliver(NativeMethods.VkLControl, false, flags: 0x10);
62	            f.Key(NativeMethods.VkRMenu, false);
63	            check("Foreign Ctrl plus right Alt does not invoke an Emacs Ctrl binding", f.Key((uint)Keys.F, false) == 0);
64	            f.Key((uint)Keys.F, true);
65	            f.Key(NativeMethods.VkRMenu, true);
66	            f.Platform.Deliver(NativeMethods.VkLControl, true, flags: 0x10);
67	        }
68	        check("Repeated AltGr-style sequences leave no Ctrl/Alt state",
69	            !f.Flag(Controls[0], "IsDown") && !f.AltDown(false) && f.Platform.AllUp);
70	        f.Platform.Sent.Clear();
71	        check("Plain F after foreign Ctrl/Alt sequence passes", f.Key((uint)Keys.F, false) == 0);
72	        f.Key((uint)Keys.F, true);
73	        check("Plain input has no modifier reinjection", f.Platform.Sent.Count == 0);
74	    }
75	
76	    private static void ExcludeStaleSide(uint key, bool passed, Action<string, bool> check)
77	    {
78	        foreach (var external in new[] { false, true })
79	        {
80	            using var f = new Fixture();
81	            f.Visible(key, passed, released: true);
82	            var other = key == Controls[0] ? Controls[1] : Controls[0];
83	            if (external) f.Platform.SetDown(other, true); // Native Ctrl not owned by this service.
84	            else f.Key(other, false);
85	            f.Platform.Sent.Clear();
86	            check($"{key:X}/{passed}/{external}: live opposite Ctrl still invokes Emacs", f.Key((uint)Keys.F, false) == 1);
87	            f.Key((uint)Keys.F, true);
88	            check("Excluded side never becomes hidden or consumed", !f.Flag(key, "HiddenFromForeground") && !f.Flag(key, "ConsumedByEmacs"));
89	            check("Opposite Ctrl emits the expected action", f.Platform.Sent.Contains(((uint)Keys.Right, false)));
90	            f.Tap((uint)Keys.X);
91	            f.Mouse();
92	            check("Neither Consume nor Promote sends the excluded Ctrl", f.Platform.Sent.All(e => e.Key != key));
93	        }
94	        using var generic = new Fixture();
95	        generic.Visible(key, passed, released: true);
96	        generic.Platform.SetDown(NativeMethods.VkControl, true);
97	        check("Generic Ctrl does not revive a stale side", generic.Key((uint)Keys.F, false) == 0);
98	        generic.Key((uint)Keys.F, true);
99	        generic.Tap((uint)Keys.X);
100	        check("Generic Ctrl cannot hide or reinject stale Ctrl", !generic.Flag(key, "HiddenFromForeground") && generic.Platform.Sent.Count == 0);
101	        generic.Platform.SetDown(NativeMethods.VkControl, false);
102	        generic.Tap(NativeMethods.VkRMenu);
103	        check("Stale Ctrl does not prevent a normal Alt IME tap",
104	            generic.Platform.Sent.Contains((JapaneseImeKey.ImeOnVirtualKey, false)) &&
105	            generic.Platform.Sent.All(e => e.Key != key));
106	    }
107	
108	    private static void Repress(uint key, bool passed, Action<string, bool> check)
109	    {
110	        using var f = new Fixture();
111	        f.Visible(key, passed, released: true);
112	        f.Tick(); // A pending release confirmation must be invalidated by down.
113	        check($"{key:X}/{passed}: pressing Ctrl again passes to Windows", f.Key(key, false) == 0);
114	        check("Repress transfers ownership to original input", f.Flag(key, "OriginalDownPassed") && !f.Flag(key, "NativeDownSent"));
115	        f.Tap((uint)Keys.C);
116	        check("Ctrl+C passes without synthesis", f.Platform.Down(key) && f.Platform.Sent.Count == 0);
117	        for (var i = 0; i < 3; i++) check("Native Ctrl repeats pass", f.Key(key, false) == 0);
118	        f.Platform.SetDown(key, false); // Another missing release on the new gesture.
119	        f.Tick(1000);
120	        check("Repress starts a fresh confirmation interval", f.Flag(key, "IsDown"));
121	        f.Tick(1000);
122	        check("New gesture can recover after its own confirmation", !f.Flag(key, "IsDown"));
123	        f.Key(key, true);
124	        check("Recovery followed by delayed up never creates Ctrl tap", f.Platform.Sent.Count == 0);
125	        f.Key(key, false);
126	        check("Fresh press after recovery is deferred normally", f.Flag(key, "HiddenFromForeground"));
127	        f.Key(key, true);
128	        check("Fresh Ctrl tap after recovery remains paired", f.Platform.Sent.SequenceEqual(new[] { (key, false), (key, true) }) && f.Platform.AllUp);
129	    }
130	
131	    private static void Recover(uint key, bool passed, Action<string, bool> check)
132	    {
133	        using var f = new Fixture();
134	        f.Visible(key, passed, released: true);
135	        f.Platform.Reliable = false;
136	        f.Tick(); f.Tick(1000);
137	        check("Unavailable state never clears Ctrl", f.Flag(key, "IsDown"));
138	        f.Platform.Reliable = true;
139	        f.Tick(1000); f.Tick(999);
140	        check("Subsecond confirmation keeps Ctrl bookkeeping", f.Flag(key, "IsDown"));
141	        f.Platform.ForegroundWindow = 2;
142	        f.Tick(1);
143	        check("Foreground change restarts confirmation", f.Flag(key, "IsDown"));
144	        f.Tick(3000);
145	        check("Long observation gap restarts confirmation", f.Flag(key, "IsDown"));
146	        f.Platform.ForegroundWindow = 0;
147	        f.Tick(1000);
148	        f.Platform.ForegroundWindow = 2;
149	        f.Tick(1000);
150	        check("Missing foreground discards prior confirmation", f.Flag(key, "IsDown"));
151	        // Use the real SendInput wrapper, with a fake empty send, to verify that
152	        // reentrant maintenance discards confirmation while input is in flight.
153	        f.Platform.OnSend = () => f.Tick(1000);
154	        typeof(AltInputService).GetMethod("SendKeyboardInputs", Private)!.Invoke(f.Service, [Array.Empty<NativeMethods.Input>()]);
155	        f.Tick(1000);
156	        check("In-flight maintenance requires fresh Ctrl confirmation", f.Flag(key, "IsDown"));
157	        f.Tick(1000);
158	        check($"{key:X}/{passed}: guarded release clears bookkeeping only", !f.Flag(key, "IsDown") && f.Platform.Sent.Count == 0);
159	        check("Recovery requests an idle hook renewal", (bool)typeof(AltInputService).GetField("_refreshRequested", Private)!.GetValue(f.Service)!);
160	    }
161	
162	    private static void PreserveHeld(uint key, bool passed, Action<string, bool> check)
163	    {
164	        using var f = new Fixture();
165	        f.Visible(key, passed, released: false);
166	        for (var i = 0; i < 120; i++) f.Tick(1000);
167	        check("120 second visible Ctrl hold is preserved", f.Flag(key, "IsDown") && f.Platform.Down(key));
168	        check("Visible hold needs no guarded desktop/token queries", f.Platform.GuardedReads == 0);
169	        f.Key((uint)Keys.F, false); f.Key((uint)Keys.F, true);
170	        check("Held visible Ctrl still invokes Emacs", f.Platform.Sent.Contains(((uint)Keys.Right, false)));
171	        f.Tap((uint)Keys.S);
172	        check("Held Ctrl is promoted back for native Ctrl+S", f.Platform.Down(key));
173	        f.Key(key, true);
174	        check("Held Ctrl releases normally after mixed input", !f.Flag(key, "IsDown") && f.Platform.AllUp);
175	    }
176	
177	    private static void PreserveHidden(uint key, Action<string, bool> check)
178	    {
179	        using var f = new Fixture();
180	        f.Key(key, false);
181	        for (var i = 0; i < 120; i++) f.Tick(1000);
182	        check("120 second hidden Ctrl hold remains active", f.Flag(key, "HiddenFromForeground"));
183	        check("Hidden hold adds no guarded sampling", f.Platform.GuardedReads == 0);
184	        f.Key((uint)Keys.F, false); f.Key((uint)Keys.F, true);
185	        check("Hidden Ctrl still invokes Emacs after long hold", f.Platform.Sent.Contains(((uint)Keys.Right, false)));
186	        for (var i = 0; i < 120; i++) f.Tick(1000);
187	        check("Consumed hidden Ctrl is not recovered", f.Flag(key, "IsDown") && f.Flag(key, "ConsumedByEmacs"));
188	        f.Tap((uint)Keys.S);
189	        check("Legitimate consumed Ctrl can still be promoted", f.Platform.Down(key));
190	        f.Key(key, true);
191	        check("Hidden Ctrl gesture eventually releases", f.Platform.AllUp);
192	    }
