194	    private static void SamplingAndCost(Action<string, bool> check)
195	    {
196	        using var f = new Fixture();
197	        var tick = typeof(AltInputService).GetMethod("ReconcileReleasedModifiers", Private)!.CreateDelegate<Action>(f.Service);
198	        for (var i = 0; i < 10000; i++) tick();
199	        var allocated = GC.GetAllocatedBytesForCurrentThread();
200	        var start = Stopwatch.GetTimestamp();
201	        for (var i = 0; i < 100000; i++) tick();
202	        var ms = Stopwatch.GetElapsedTime(start).TotalMilliseconds;
203	        var bytes = GC.GetAllocatedBytesForCurrentThread() - allocated;
204	        check("Idle modifier maintenance adds no allocation or state queries",
205	            bytes == 0 && f.Platform.StateReads == 0 && f.Platform.GuardedReads == 0);
206	        Console.WriteLine($"Idle modifier maintenance: 100000 calls, {ms:F2} ms, {bytes} bytes, no OS state queries (local probe).");
207	        f.Key(Controls[0], false); f.Key(NativeMethods.VkLMenu, false);
208	        f.Platform.SetDown(Controls[0], false); f.Platform.SetDown(NativeMethods.VkLMenu, false);
209	        // Recovery is independent of the later idle/all-keys-up gate used for
210	        // hook renewal (a held IME virtual key can keep that gate closed).
211	        f.Platform.SetDown(0x19, true);
212	        f.Tick();
213	        check("Alt and Ctrl share one guarded read per timer tick", f.Platform.GuardedReads == 1);
214	        f.Tick(1000);
215	        check("Shared guarded sample can recover both Ctrl and Alt", !f.Flag(Controls[0], "IsDown") &&
216	            !f.AltDown(true));
217	        check("Ctrl recovery does not release unrelated held input", f.Platform.Down(0x19));
218	        f.Platform.SetDown(0x19, false);
219	    }
220	
221	    private static void RecoveryLog(Action<string, bool> check)
222	    {
223	        var directory = Path.Combine(Path.GetTempPath(), "AltHenkan-CtrlRecovery-" + Guid.NewGuid().ToString("N"));
224	        Directory.CreateDirectory(directory);
225	        var path = Path.Combine(directory, "diagnostics.log");
226	        try
227	        {
228	            DiagnosticLog.Initialize(path: path);
229	            using (var f = new Fixture())
230	            {
231	                f.Visible(Controls[0], false, released: true);
232	                f.Tick(); f.Tick(1000);
233	            }
234	            DiagnosticLog.Shutdown();
235	            check("Ctrl recovery is recorded in the normal diagnostic log", File.ReadAllText(path).Contains("Recovered released Left Ctrl:"));
236	            var entries = File.ReadAllLines(path + ".input").Where(l => l.Contains("reason=RecoveredControl")).ToArray();
237	            check("Ctrl recovery trace identifies side and before/after state", entries.Length == 2 &&
238	                entries.All(l => l.Contains("key=LeftControl")) && entries[0].Contains("state=0x340005") &&
239	                entries[1].Contains("index=1") && entries[1].Contains("state=0x340000"));
240	        }
241	        finally { DiagnosticLog.Shutdown(); Directory.Delete(directory, true); }
242	    }
243	
244	    private sealed class Fixture : IDisposable
245	    {
246	        public readonly ModifierReleaseTests.Platform Platform = new() { Now = Environment.TickCount64 };
247	        public readonly AltInputService Service;
248	        private readonly Action _tick;
249	        public Fixture()
250	        {
251	            Service = ModifierReleaseTests.Create(Platform, true);
252	            _tick = typeof(AltInputService).GetMethod("ReconcileReleasedModifiers", Private)!.CreateDelegate<Action>(Service);
253	        }
254	        public nint Key(uint key, bool up) => Platform.Deliver(key, up);
255	        public void Tap(uint key) { Key(key, false); Key(key, true); }
256	        public void Tick(long elapsed = 0) { Platform.Now += elapsed; _tick(); }
257	        public bool Flag(uint key, string name)
258	            => StateFlag(key == Controls[0] ? "_leftControl" : "_rightControl", name);
259	        public bool AltDown(bool left) => StateFlag(left ? "_leftAlt" : "_rightAlt", "IsDown");
260	        private bool StateFlag(string field, string name)
261	        {
262	            var state = typeof(AltInputService).GetField(field, Private)!.GetValue(Service)!;
263	            return (bool)state.GetType().GetProperty(name)!.GetValue(state)!;
264	        }
265	        public void Visible(uint key, bool passed, bool released)
266	        {
267	            if (passed) Key((uint)Keys.X, false);
268	            Key(key, false);
269	            if (!passed) Key((uint)Keys.X, false);
270	            Key((uint)Keys.X, true);
271	            if (released) Platform.SetDown(key, false);
272	            Platform.Sent.Clear();
273	        }
274	        public void Mouse()
275	        {
276	            var callback = typeof(AltInputService).GetMethod("MouseHookCallback", Private)!.CreateDelegate<NativeMethods.HookProc>(Service);
277	            var data = Marshal.AllocHGlobal(Marshal.SizeOf<NativeMethods.MouseLlHookStruct>());
278	            try
279	            {
280	                Marshal.StructureToPtr(new NativeMethods.MouseLlHookStruct(), data, false);
281	                callback(0, NativeMethods.WmLButtonDown, data);
282	                callback(0, NativeMethods.WmLButtonUp, data);
283	            }
284	            finally { Marshal.FreeHGlobal(data); }
285	        }
286	        public void Dispose() => Service.Dispose();
287	    }
288	}
