3	namespace AltHenkan;
4	
5	internal sealed partial class AltInputService
6	{
7	    private long _traceObservationSequence;
8	    private long _traceObservation;
9	    private long _traceParent;
10	    private long _traceBatchSequence;
11	    private long _traceBatch;
12	    private uint _traceToken;
13	    private InputTraceVerdict _traceVerdict;
14	    private InputTraceReason _traceReason;
15	
16	    internal static bool IsOwnInput(nuint marker) => unchecked((uint)marker) == (uint)OwnInputMarker;
17	    internal static uint TraceToken(nuint marker) =>
18	        Environment.Is64BitProcess && IsOwnInput(marker) ? (uint)((ulong)marker >> 32) : 0;
19	    private nuint NextInputMarker()
20	    {
21	        if (!Environment.Is64BitProcess) return OwnInputMarker;
22	        if (++_traceToken == 0) ++_traceToken;
23	        return unchecked((nuint)(((ulong)_traceToken << 32) | (uint)OwnInputMarker));
24	    }
25	
26	    private InputTraceSnapshot TraceSnapshot()
27	    {
28	        static uint Bits(bool down, bool passed, bool sent, bool consumed) =>
29	            (down ? 1u : 0) | (passed ? 2u : 0) | (sent ? 4u : 0) | (consumed ? 8u : 0);
