3	// Pure gesture state: no Windows API, disk I/O or UI operations.
4	internal sealed class EmacsKeyboardState
5	{
6	    private bool _capsLockCaptured;
7	    private bool _capsLockPassed;
8	    private readonly Dictionary<uint, EmacsShortcut> _capturedKeys = [];
9	    private readonly HashSet<uint> _passedKeys = [];
10	
11	    public bool Active { get; private set; }
12	    public bool GestureActive => _capsLockCaptured || _capturedKeys.Count > 0;
13	    public int CapturedKeyCount => _capturedKeys.Count;
14	    public bool CapsLockCaptured => _capsLockCaptured;
15	
16	    public bool Disable()
17	        => SetActive(false);
18	
19	    public bool SetActive(bool active)
20	    {
21	        var changed = Active != active;
22	        Active = active;
23	        // Keep captured key-ups paired even if settings change while a key is held.
24	        return changed;
25	    }
26	
27	    public bool HandleCapsLock(bool keyDown, bool enabled, out bool modeChanged)
28	    {
29	        modeChanged = false;
30	        if (!keyDown)
31	        {
32	            var captured = _capsLockCaptured;
33	            _capsLockCaptured = false;
34	            _capsLockPassed = false;
35	            return captured;
36	        }
37	        if (_capsLockCaptured)
38	        {
39	            return true;
40	        }
41	        if (_capsLockPassed) return false;
42	        if (!enabled)
43	        {
44	            _capsLockPassed = true;
45	            return false;
46	        }
47	        _capsLockCaptured = true;
48	        Active = !Active;
49	        modeChanged = true;
50	        return true;
51	    }
52	
53	    public bool HandleKey(uint key, bool keyDown, bool enabled,
54	        NavigationModifiers modifiers, EmacsShortcutSettings settings, out EmacsBinding? binding,
55	        EmacsSideFilter? sideFilter = null)
56	    {
57	        binding = null;
58	        if (!EmacsBindings.IsSourceKey(key)) return false;
59	        if (!keyDown)
60	        {
61	            _passedKeys.Remove(key);
62	            return _capturedKeys.Remove(key);
63	        }
64	        if (_passedKeys.Contains(key)) return false;
65	        var captured = _capturedKeys.TryGetValue(key, out var originalShortcut);
66	        if (enabled && Active)
67	        {
68	            binding = EmacsBindings.Resolve(key, modifiers, settings, sideFilter);
69	            if (binding is not null && (!captured || originalShortcut == binding.Shortcut))
70	            {
71	                _capturedKeys[key] = binding.Shortcut;
72	                return true;
73	            }
74	        }
75	        binding = null;
76	        if (!captured) _passedKeys.Add(key);
77	        return captured;
78	    }
79	
80	    public void ResetTransient()
81	    {
82	        _capsLockCaptured = false;
83	        _capsLockPassed = false;
84	        _capturedKeys.Clear();
85	        _passedKeys.Clear();
86	        // A periodic hook renewal must not change the user's selected mode.
87	    }
88	
89	}
90

